<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/includes/auth.php'; require_once __DIR__ . '/layout.php'; require_once dirname(__DIR__) . '/services/teacher_students.php';
$current = tuman_require_role('TEACHER'); $error = null; $students = [];
try { $students = tuman_teacher_students(tuman_database(), $current['id']); } catch (Throwable $exception) { error_log('Tuman teacher student list failed: ' . $exception->getMessage()); $error = 'Students cannot be loaded right now.'; }
tuman_teacher_page_start('My students');
?>
<h1>My students</h1><?php if ($error): ?><p role="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php else: ?><p><a class="button" href="/Tuman/teacher/student-create.php">Enrol student</a></p><div style="overflow-x:auto"><table><thead><tr><th>Name</th><th>Username</th><th>Contact</th><th>Started</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($students as $student): ?><tr><td><?= htmlspecialchars(trim($student['first_name'] . ' ' . ($student['last_name'] ?? '')), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($student['username'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($student['phone'] ?? $student['email'] ?? '—', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($student['start_date'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($student['assignment_status'], ENT_QUOTES, 'UTF-8') ?></td><td><a href="/Tuman/teacher/student-view.php?id=<?= (int) $student['assignment_id'] ?>">View</a> · <a href="/Tuman/teacher/student-edit.php?id=<?= (int) $student['assignment_id'] ?>">Edit</a><?php if ($student['assignment_status'] === 'ACTIVE'): ?> · <a href="/Tuman/teacher/student-status.php?id=<?= (int) $student['assignment_id'] ?>">Deactivate</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; tuman_teacher_page_end(); ?>
